-- ACID SQLite twin of Phase 2 grains for CI. Not a second product database.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS ref__data_source (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ref__venue (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ref__asset (id TEXT PRIMARY KEY, symbol TEXT NOT NULL UNIQUE, name TEXT NOT NULL, asset_class TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ref__timeframe (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, seconds INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ref__instrument (id TEXT PRIMARY KEY, venue_id TEXT NOT NULL REFERENCES ref__venue(id), base_asset_id TEXT NOT NULL REFERENCES ref__asset(id), quote_asset_id TEXT NOT NULL REFERENCES ref__asset(id), symbol TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (venue_id, symbol, kind));
CREATE TABLE IF NOT EXISTS ops__dataset_snapshot (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, data_source_id TEXT REFERENCES ref__data_source(id), as_of_time TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ops__ingestion_run (id TEXT PRIMARY KEY, dataset_snapshot_id TEXT REFERENCES ops__dataset_snapshot(id), status TEXT NOT NULL, started_at TEXT, finished_at TEXT, config TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ops__canonicalization_run (id TEXT PRIMARY KEY, ingestion_run_id TEXT REFERENCES ops__ingestion_run(id), version TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ops__schema_gate (id TEXT PRIMARY KEY, phase TEXT NOT NULL UNIQUE, approved INTEGER NOT NULL, ingestion_enabled INTEGER NOT NULL, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research__indicator_definition (id TEXT PRIMARY KEY, family_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research__feature_definition (id TEXT PRIMARY KEY, indicator_id TEXT REFERENCES research__indicator_definition(id), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research__feature_version (id TEXT PRIMARY KEY, feature_id TEXT NOT NULL REFERENCES research__feature_definition(id), version TEXT NOT NULL, formula_ref TEXT, created_at TEXT NOT NULL, UNIQUE (feature_id, version));
CREATE TABLE IF NOT EXISTS research__parameter_definition (id TEXT PRIMARY KEY, feature_id TEXT NOT NULL REFERENCES research__feature_definition(id), name TEXT NOT NULL, topology TEXT NOT NULL, domain TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research__parameter_set (id TEXT PRIMARY KEY, feature_version_id TEXT NOT NULL REFERENCES research__feature_version(id), signature TEXT NOT NULL, param_values TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (feature_version_id, signature));
CREATE TABLE IF NOT EXISTS research__parameter_region (id TEXT PRIMARY KEY, feature_id TEXT NOT NULL REFERENCES research__feature_definition(id), code TEXT NOT NULL UNIQUE, dimension TEXT NOT NULL, lo REAL NOT NULL, hi REAL NOT NULL, detection TEXT NOT NULL, created_at TEXT NOT NULL, CHECK (hi >= lo));
CREATE TABLE IF NOT EXISTS research__parameter_region_member (region_id TEXT NOT NULL REFERENCES research__parameter_region(id), parameter_set_id TEXT NOT NULL REFERENCES research__parameter_set(id), PRIMARY KEY (region_id, parameter_set_id));
CREATE TABLE IF NOT EXISTS research__outcome_definition (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, horizon_bars INTEGER, description TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research__relationship_definition (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, version TEXT NOT NULL, outcome_id TEXT, expression TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research__combination_request (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, relationship_id TEXT REFERENCES research__relationship_definition(id), request_hash TEXT NOT NULL UNIQUE, specification TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS raw__market_event (id TEXT PRIMARY KEY, data_source_id TEXT NOT NULL REFERENCES ref__data_source(id), source_record_id TEXT NOT NULL, instrument_id TEXT NOT NULL REFERENCES ref__instrument(id), timeframe_id TEXT NOT NULL REFERENCES ref__timeframe(id), dataset_snapshot_id TEXT NOT NULL REFERENCES ops__dataset_snapshot(id), ingestion_run_id TEXT NOT NULL REFERENCES ops__ingestion_run(id), event_time TEXT NOT NULL, knowledge_time TEXT NOT NULL, payload TEXT NOT NULL, checksum TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (data_source_id, source_record_id), CHECK (knowledge_time >= event_time));
CREATE TABLE IF NOT EXISTS market__ohlcv_bar (id TEXT PRIMARY KEY, instrument_id TEXT NOT NULL REFERENCES ref__instrument(id), venue_id TEXT NOT NULL REFERENCES ref__venue(id), timeframe_id TEXT NOT NULL REFERENCES ref__timeframe(id), dataset_snapshot_id TEXT NOT NULL REFERENCES ops__dataset_snapshot(id), raw_event_id TEXT NOT NULL REFERENCES raw__market_event(id), canonicalization_run_id TEXT NOT NULL REFERENCES ops__canonicalization_run(id), event_time TEXT NOT NULL, knowledge_time TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume REAL NOT NULL, canonicalization_version TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (instrument_id, venue_id, timeframe_id, event_time, canonicalization_version), CHECK (knowledge_time >= event_time));
CREATE TABLE IF NOT EXISTS feature__observation (id TEXT PRIMARY KEY, feature_version_id TEXT NOT NULL REFERENCES research__feature_version(id), parameter_set_id TEXT NOT NULL REFERENCES research__parameter_set(id), instrument_id TEXT NOT NULL REFERENCES ref__instrument(id), timeframe_id TEXT NOT NULL REFERENCES ref__timeframe(id), dataset_snapshot_id TEXT NOT NULL REFERENCES ops__dataset_snapshot(id), event_time TEXT NOT NULL, knowledge_time TEXT NOT NULL, value REAL NOT NULL, created_at TEXT NOT NULL, UNIQUE (feature_version_id, parameter_set_id, instrument_id, timeframe_id, event_time), CHECK (knowledge_time >= event_time));
CREATE TABLE IF NOT EXISTS ops__current_market_state (id TEXT PRIMARY KEY, instrument_id TEXT NOT NULL REFERENCES ref__instrument(id), venue_id TEXT NOT NULL REFERENCES ref__venue(id), timeframe_id TEXT NOT NULL REFERENCES ref__timeframe(id), event_time TEXT NOT NULL, as_of_time TEXT NOT NULL, state_version TEXT NOT NULL, payload TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (instrument_id, venue_id, timeframe_id));
CREATE TABLE IF NOT EXISTS ops__current_feature_value (id TEXT PRIMARY KEY, feature_version_id TEXT NOT NULL REFERENCES research__feature_version(id), parameter_set_id TEXT NOT NULL REFERENCES research__parameter_set(id), instrument_id TEXT NOT NULL REFERENCES ref__instrument(id), timeframe_id TEXT NOT NULL REFERENCES ref__timeframe(id), event_time TEXT NOT NULL, as_of_time TEXT NOT NULL, value REAL, updated_at TEXT NOT NULL, UNIQUE (feature_version_id, parameter_set_id, instrument_id, timeframe_id));
CREATE TABLE IF NOT EXISTS ops__current_regime_state (id TEXT PRIMARY KEY, instrument_id TEXT NOT NULL REFERENCES ref__instrument(id), timeframe_id TEXT NOT NULL REFERENCES ref__timeframe(id), regime_family TEXT NOT NULL, label TEXT NOT NULL, event_time TEXT NOT NULL, as_of_time TEXT NOT NULL, provenance TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (instrument_id, timeframe_id, regime_family));
CREATE TABLE IF NOT EXISTS ops__operational_relationship_applicability (id TEXT PRIMARY KEY, relationship_code TEXT NOT NULL, instrument_id TEXT REFERENCES ref__instrument(id), timeframe_id TEXT REFERENCES ref__timeframe(id), regime_bucket TEXT, active INTEGER NOT NULL, score REAL, state_version TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ops__persist_watermark (stream TEXT PRIMARY KEY, last_event_time TEXT NOT NULL, last_source_record_id TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_ohlcv_inst_tf_time ON market__ohlcv_bar (instrument_id, timeframe_id, event_time);
CREATE INDEX IF NOT EXISTS ix_ohlcv_knowledge ON market__ohlcv_bar (knowledge_time);
CREATE INDEX IF NOT EXISTS ix_obs_param_time ON feature__observation (parameter_set_id, event_time);
CREATE INDEX IF NOT EXISTS ix_obs_knowledge ON feature__observation (knowledge_time);
CREATE TRIGGER IF NOT EXISTS trg_raw_no_update BEFORE UPDATE ON raw__market_event BEGIN SELECT RAISE(ABORT, 'append-only raw.market_event'); END;
CREATE TRIGGER IF NOT EXISTS trg_raw_no_delete BEFORE DELETE ON raw__market_event BEGIN SELECT RAISE(ABORT, 'append-only raw.market_event'); END;
CREATE TRIGGER IF NOT EXISTS trg_bar_no_update BEFORE UPDATE ON market__ohlcv_bar BEGIN SELECT RAISE(ABORT, 'append-only market.ohlcv_bar'); END;
CREATE TRIGGER IF NOT EXISTS trg_bar_no_delete BEFORE DELETE ON market__ohlcv_bar BEGIN SELECT RAISE(ABORT, 'append-only market.ohlcv_bar'); END;
CREATE TRIGGER IF NOT EXISTS trg_obs_no_update BEFORE UPDATE ON feature__observation BEGIN SELECT RAISE(ABORT, 'append-only feature.observation'); END;
CREATE TRIGGER IF NOT EXISTS trg_obs_no_delete BEFORE DELETE ON feature__observation BEGIN SELECT RAISE(ABORT, 'append-only feature.observation'); END;
